// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address sender, address newOwner) public {
        vm.assume(sender != address(0));
        vm.assume(newOwner != address(0));
        address originalOwner = c.owner();
        vm.prank(sender);
        try c.transferOwnership(newOwner) {} catch {}
        address afterOwner = c.owner();
        if (sender != originalOwner) {
            assertEq(afterOwner, originalOwner);
        } else {
            assertTrue(true);
        }
    }
}
